import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十四章","description":"《正易心法》第三十四章——凡具于形，便具五数：丽于气者必圆（径一围三），丽于形者必方（径一围四）；天数三重之则六，地数五重之则十；四方加中央为五，加四维复之中央为十。","frontmatter":{"title":"正易心法·第三十四章","description":"《正易心法》第三十四章——凡具于形，便具五数：丽于气者必圆（径一围三），丽于形者必方（径一围四）；天数三重之则六，地数五重之则十；四方加中央为五，加四维复之中央为十。","category":"guide","aliases":["正易心法第三十四章","凡具于形便具五数","五数既具十数乃成"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-34.md","filePath":"yijing/zheng-yi-xin-fa/chapter-34.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-34.md"},v=p({...c,setup(u){const i=[{id:"z34-01",label:"一、凡具于形便具五数",showLabel:!0,sentences:[["凡具于形，便具五数。五数既具，十数乃成。"]],note:["凡是具备形体的事物，便具备「五」这个数；五数既然具备，「十」这个数就自然成立。（**本章是「形」的数**——第三十二章说「气之数」（三与六），本章说「形之数」（五与十）。**两章合观：气圆（三），形方（四／五）；气重之为六，形重之为十。**）"]},{id:"z34-02",label:"二、丽于气者必圆",showLabel:!0,sentences:[["凡",{text:"丽于气",glossary:"liyuqi"},"者，必圆，圆者，",{text:"径一而围三",glossary:"jingyiWeisan"},"。天所以有",{text:"三时",glossary:"sanshi"},"者，以其气也。"]],note:["凡是附着于气的事物，必然是圆的；圆，直径一而周长三。天所以有三时，是因为天属于气。（**「丽」是附着、依附**。**气无棱角，自然成圆**——而「径一围三」是古代对圆周率 π 的取整（π≈3）。**「三时」的一种读法是春、夏、秋**，古人于冬有休养之义；总之是「天数三」的对应。）"]},{id:"z34-03",label:"三、丽于形者必方",showLabel:!0,sentences:[["凡",{text:"丽于形",glossary:"liyuxing"},"者，必方。方者，",{text:"径一而围四",glossary:"jingyiWeisi"},"。地所以有",{text:"四方",glossary:"sifang"},"者，以其形也。"]],note:["凡是附着于形的事物，必然是方的；方，直径一而周长四。地所以有四方，是因为地属于形。（**与上段严格对举**：气——圆——径一围三——三时；形——方——径一围四——四方。**「径一围四」是严格的**（正方形周长＝4 倍边长），而「径一围三」是古人对 π 的取整——**两段的精度并不相同，这一点值得留意。**）"]},{id:"z34-04",label:"四、天数三地数五",showLabel:!0,sentences:[["天数三，重之则六。地数五，重之则十。"]],note:["天数为三，加倍则是六；地数为五，加倍则是十。（**两组数的对称**：气→三→六（第三十二章），形→五→十（本章）。**六与十，都是「重之」的结果**——不是外加的，是自身重一重。）"]},{id:"z34-05",label:"五、何谓十",showLabel:!0,sentences:[["何谓十？盖有四方，则有中央，为五。有中央四方，则有四维，",{text:"复之中央",glossary:"fuzhiZhongyang"},"，是为十也。"]],note:["什么叫做十？有四方，就有中央，合为五；有了中央和四方，就有四维（四个角），再加上中央，就是十了。（**九与十之间，只差「中央数了两次」**：四方（4）＋四维（4）＋中央（1）＝**九**（这正是九宫的格局）；**「复之中央」再数一次，则为十**——这也就是洛书九宫与河图十数的分别。）"]},{id:"z34-06",label:"六、非特地为然",showLabel:!0,sentences:[["非特地为然，凡丽于形，便具十数，解若此也。"]],note:["不只是地才如此：凡是附着于形的事物，都具备「十」这个数——解释就是这样。（**「解若此也」是麻衣的自注语**：我这里的解释就到此为止了。**这一句同时也是本章的枢纽**：从「地的方圆」推到「凡丽于形者」，**是本章的推论方向，也是它最需要检验的一步。**）"]}],o=[{id:"liyuqi",term:"丽于气",pinyin:"lì yú qì",meaning:"附着于气。丽＝附着、依附。属于气的范畴，故必圆。"},{id:"jingyiWeisan",term:"径一而围三",pinyin:"jìng yī ér wéi sān",meaning:"直径一，周长三。古代对圆周率的取整（π≈3，《周髀》《九章》并同）。"},{id:"sanshi",term:"三时",pinyin:"sān shí",meaning:"天的气数是三。一说指春、夏、秋，一说指三才。麻衣重点在天＝气＝圆＝三的推导链。"},{id:"liyuxing",term:"丽于形",pinyin:"lì yú xíng",meaning:"附着于形。属于形体的范畴，故必方。"},{id:"jingyiWeisi",term:"径一而围四",pinyin:"jìng yī ér wéi sì",meaning:"直径一，周长四。正方形周长＝4 倍边长。"},{id:"sifang",term:"四方",pinyin:"sì fāng",meaning:"东西南北四个方向。地的形数是四。"},{id:"fuzhiZhongyang",term:"复之中央",pinyin:"fù zhī zhōng yāng",meaning:"再加上中央。四维＋中央为九，再数一次中央则为十。"}];return(b,n)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",22)),e(l,{colophon:"凡具于形 · 气圆形方 · 五数既具 · 十数乃成",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十四章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（「丽」为附着之义），不作统一。本章以「径一围三」取 π≈3 之古法，属时代之常，读者可并观现代数学。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"丽于气 / 丽于形",pinyin:["lì","yú"],meaning:"丽＝附着。附着于气者（天）必圆、数三；附着于形者（地）必方、数四（＋中央为五）。"},{term:"径一围三 / 径一围四",pinyin:["jìng","yī"],meaning:"圆：直径一、周长三（π≈3 的古法）；方：直径一、周长四。"},{term:"五数的来历",pinyin:["wǔ","shù"],meaning:"四方（东西南北）＋中央＝5。这是洛书、五行「土居中央」的几何来源。"},{term:"十数的来历",pinyin:["shí","shù"],meaning:"四方＋四维＋中央＝9（九宫）；「复之中央」再数一次中央则为 10。"},{term:"解若此也",pinyin:["jiě","ruò"],meaning:"麻衣的自注语：解释就是到此为止。同时也是本章从「地」推到「凡有形者」的推论边界。"}]}),n[3]||(n[3]=t("",23))])}}});export{m as __pageData,v as default};
